/**
 * Petshop Invoice Doc Type Fix v2 (LIVE, GLOBAL)
 * Perjungia doc_type PRIES generacija ant completed. GLOBAL - veikia ir admin/REST kontekste.
 */
if ( ! defined( 'ABSPATH' ) ) { return; }
add_action( 'woocommerce_order_status_completed', function( $order_id ) {
	if ( ! function_exists( 'petshop_get_invoice_document_type' ) ) { return; }
	$order = wc_get_order( $order_id );
	if ( ! $order ) { return; }
	$dt = petshop_get_invoice_document_type( $order );
	if ( $order->get_meta( '_petshop_invoice_document_type' ) !== $dt ) {
		$order->update_meta_data( '_petshop_invoice_document_type', $dt );
		$order->delete_meta_data( '_wcdn_invoice_pdf' );
		$order->delete_meta_data( '_wcdn_invoice_pdf_token' );
		$order->save();
	}
}, 1 );

